mapper.select:
		SELECT 
		       FINPROD_ID finprodId,
		       VAL_DATE valDate,
		       VALUATION netValue
        FROM 
               FIN_PRODUCT_VALUATION 
        WHERE 
               FINPROD_ID=#{finprodId} 
               AND FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
               AND DATE_FORMAT(VAL_DATE,'%Y-%m-%d') = #{valDate}
